# Complete CS:GO Website HTML

Here's a complete, modern CS:GO themed website with HTML, CSS, and JavaScript all in one file:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CS:GO Elite - Counter-Strike Global Offensive Hub</title>
<style>
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
        font-family: 'Segoe UI', Tahoma, sans-serif;
    }

    body {
        background: #0a0e17;
        color: #e0e0e0;
        overflow-x: hidden;
    }

    /* Navigation */
    nav {
        position: fixed;
        top: 0;
        width: 100%;
        background: rgba(10, 14, 23, 0.95);
        backdrop-filter: blur(10px);
        padding: 15px 50px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        z-index: 1000;
        border-bottom: 2px solid #f39c12;
    }

    .logo {
        font-size: 28px;
        font-weight: bold;
        color: #f39c12;
        letter-spacing: 2px;
    }

    .logo span {
        color: #fff;
    }

    .nav-links {
        display: flex;
        list-style: none;
        gap: 30px;
    }

    .nav-links a {
        color: #fff;
        text-decoration: none;
        font-weight: 500;
        transition: color 0.3s;
        text-transform: uppercase;
        font-size: 14px;
    }

    .nav-links a:hover {
        color: #f39c12;
    }

    .play-btn {
        background: #f39c12;
        color: #0a0e17;
        padding: 10px 25px;
        border: none;
        cursor: pointer;
        font-weight: bold;
        text-transform: uppercase;
        transition: all 0.3s;
        clip-path: polygon(10% 0, 100% 0, 90% 100%, 0 100%);
    }

    .play-btn:hover {
        background: #fff;
        transform: scale(1.05);
    }

    /* Hero Section */
    .hero {
        height: 100vh;
        background: linear-gradient(135deg, rgba(10,14,23,0.85), rgba(10,14,23,0.6)),
            url('https://images.unsplash.com/photo-1542751371-adc38448a05e?w=1920') center/cover;
        display: flex;
        align-items: center;
        justify-content: center;
        text-align: center;
        position: relative;
    }

    .hero-content {
        max-width: 800px;
        padding: 20px;
        animation: fadeInUp 1s ease;
    }

    @keyframes fadeInUp {
        from {
            opacity: 0;
            transform: translateY(30px);
        }
        to {
            opacity: 1;
            transform: translateY(0);
        }
    }

    .hero h1 {
        font-size: 72px;
        margin-bottom: 20px;
        text-transform: uppercase;
        letter-spacing: 4px;
        color: #fff;
        text-shadow: 0 0 20px rgba(243, 156, 18, 0.5);
    }

    .hero h1 span {
        color: #f39c12;
    }

    .hero p {
        font-size: 20px;
        margin-bottom: 30px;
        color: #ccc;
    }

    .cta-buttons {
        display: flex;
        gap: 20px;
        justify-content: center;
    }

    .btn {
        padding: 15px 40px;
        text-decoration: none;
        font-weight: bold;
        text-transform: uppercase;
        transition: all 0.3s;
        cursor: pointer;
        border: 2px solid #f39c12;
    }

    .btn-primary {
        background: #f39c12;
        color: #0a0e17;
    }

    .btn-secondary {
        background: transparent;
        color: #f39c12;
    }

    .btn:hover {
        background: #fff;
        border-color: #fff;
        color: #0a0e17;
        transform: translateY(-3px);
    }

    /* Sections */
    section {
        padding: 80px 50px;
    }

    .section-title {
        text-align: center;
        font-size: 42px;
        margin-bottom: 50px;
        text-transform: uppercase;
        letter-spacing: 3px;
    }

    .section-title span {
        color: #f39c12;
    }

    /* Features */
    .features {
        background: #111722;
    }

    .features-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
        gap: 30px;
        max-width: 1200px;
        margin: 0 auto;
    }

    .feature-card {
        background: #1a2332;
        padding: 40px 30px;
        text-align: center;
        border: 1px solid #2a3548;
        transition: all 0.3s;
        position: relative;
        overflow: hidden;
    }

    .feature-card::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        width: 0;
        height: 3px;
        background: #f39c12;
        transition: width 0.4s;
    }

    .feature-card:hover::before {
        width: 100%;
    }

    .feature-card:hover {
        transform: translateY(-10px);
        border-color: #f39c12;
    }

    .feature-icon {
        font-size: 50px;
        margin-bottom: 20px;
    }

    .feature-card h3 {
        font-size: 22px;
        margin-bottom: 15px;
        color: #f39c12;
        text-transform: uppercase;
    }

    /* Maps */
    .maps-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
        gap: 25px;
        max-width: 1200px;
        margin: 0 auto;
    }

    .map-card {
        position: relative;
        height: 250px;
        overflow: hidden;
        cursor: pointer;
        border: 1px solid #2a3548;
    }

    .map-card img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        transition: transform 0.5s;
    }

    .map-card:hover img {
        transform: scale(1.1);
    }

    .map-overlay {
        position: absolute;
        bottom: 0;
        left: 0;
        right: 0;
        background: linear-gradient(transparent, rgba(10,14,23,0.95));
        padding: 30px 20px 20px;
    }

    .map-overlay h3 {
        font-size: 24px;
        color: #f39c12;
        text-transform: uppercase;
        margin-bottom: 5px;
    }

    .map-overlay p {
        color: #ccc;
        font-size: 14px;
    }

    /* Weapons */
    .weapons {
        background: #111722;
    }

    .weapons-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
        gap: 20px;
        max-width: 1200px;
        margin: 0 auto;
    }

    .weapon-card {
        background: #1a2332;
        padding: 25px;
        text-align: center;
        border: 1px solid #2a3548;
        transition: all 0.3s;
    }

    .weapon-card:hover {
        border-color: #f39c12;
        background: #202b3e;
    }

    .weapon-emoji {
        font-size: 60px;
        margin-bottom: 15px;
    }

    .weapon-card h3 {
        color: #f39c12;
        margin-bottom: 10px;
    }

    .weapon-stat {
        display: flex;
        justify-content: space-between;
        margin: 8px 0;
        font-size: 14px;
    }

    .stat-bar {
        background: #0a0e17;
        height: 6px;
        margin-top: 4px;
        overflow: hidden;
    }

    .stat-fill {
        height: 100%;
        background: #f39c12;
    }

    /* News */
    .news-grid {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
        gap: 30px;
        max-width: 1200px;
        margin: 0 auto;
    }

    .news-card {
        background: #1a2332;
        overflow: hidden;
        transition: transform 0.3s;
        border: 1px solid #2a3548;
    }

    .news-card:hover {
        transform: translateY(-5px);
    }

    .news-img {
        height: 200px;
        background: linear-gradient(135deg, #f39c12, #c0392b);
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 60px;
    }

    .news-content {
        padding: 25px;
    }

    .news-date {
        color: #f39c12;
        font-size: 12px;
        text-transform: uppercase;
        margin-bottom: 10px;
    }

    .news-content h3 {
        margin-bottom: 10px;
        color: #fff;
    }

    .news-content p {
        color: #aaa;
        font-size: 14px;
        line-height: 1.6;
    }

    /* Footer */
    footer {
        background: #060912;
        padding: 50px 50px 20px;
        border-top: 2px solid #f39c12;
    }

    .footer-content {
        max-width: 1200px;
        margin: 0 auto;
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
        gap: 40px;
        margin-bottom: 30px;
    }

    .footer-col h4 {
        color: #f39c12;
        margin-bottom: 20px;
        text-transform: uppercase;
        font-size: 16px;
    }

    .footer-col ul {
        list-style: none;
    }

    .footer-col ul li {
        margin-bottom: 10px;
    }

    .footer-col a {
        color: #aaa;
        text-decoration: none;
        font-size: 14px;
        transition: color 0.3s;
    }

    .footer-col a:hover {
        color: #f39c12;
    }

    .social-links {
        display: flex;
        gap: 15px;
    }

    .social-links a {
        width: 40px;
        height: 40px;
        background: #1a2332;
        display: flex;
        align-items: center;
        justify-content: center;
        font-size: 20px;
        transition: all 0.3s;
    }

    .social-links a:hover {
        background: #f39c12;
        color: #0a0e17;
    }

    .footer-bottom {
        text-align: center;
        padding-top: 30px;
        border-top: 1px solid #2a3548;
        color: #777;
        font-size: 13px;
    }

    /* Responsive */
    @media (max-width: 768px) {
        nav {
            padding: 15px 20px;
        }
        .nav-links {
            display: none;
        }
        .hero h1 {
            font-size: 42px;
        }
        section {
            padding: 60px 20px;
        }
        .cta-buttons {
            flex-direction: column;
        }
    }
</style>
</head>
